## Code Example
```
// Example mutation operator
function mutateCode(code) {
  return code.replace('>', '<=').replace('<', '>=').replace('==', '!=').replace('!=', '==');
}

// Mutation testing framework
class MutationTester {
  runMutations(testSuite, sourceCode) {
    const mutations = this.generateMutations(sourceCode);
    let survivedMutations = 0;

    for (const mutation of mutations) {
      const result = testSuite.run(mutation.code);
      if (result.passed) survivedMutations++;
    }

    return {
      mutationScore: ((mutations.length - survivedMutations) / mutations.length) * 100,
      survivedMutations
    };
  }
}
```
